function posterizeProcess(data,w,h,opts){
  opts=opts||{};
  var levels=opts.levels!=null?opts.levels:4;
  if(levels<2)levels=2; else if(levels>256)levels=256;
  var step=255/(levels-1);
  var out=new Uint8ClampedArray(data.length);
  for(var i=0;i<data.length;i+=4){
    out[i]=Math.round(data[i]/step)*step;
    out[i+1]=Math.round(data[i+1]/step)*step;
    out[i+2]=Math.round(data[i+2]/step)*step;
    out[i+3]=data[i+3];
  }
  return out;
}

var EXPORTS={posterizeProcess:posterizeProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PosterizeForgePure = EXPORTS; }
